"use client";

import { useActionState } from "react";
import type { ReviewState } from "./actions";

type Props = {
  action: (previous: ReviewState, formData: FormData) => Promise<ReviewState>;
};

export function ReviewForm({ action }: Props) {
  const [state, formAction, pending] = useActionState(action, {});

  return (
    <form action={formAction}>
      <label>
        Rating
        <select name="rating" defaultValue={state.values?.rating ?? ""}>
          <option value="">Choose</option>
          {[5, 4, 3, 2, 1].map((n) => (
            <option key={n} value={n}>{n} stars</option>
          ))}
        </select>
      </label>
      {state.errors?.rating && <p>{state.errors.rating[0]}</p>}

      <label>
        Title
        <input name="title" defaultValue={state.values?.title} />
      </label>
      {state.errors?.title && <p>{state.errors.title[0]}</p>}

      <label>
        Review
        <textarea name="body" defaultValue={state.values?.body} />
      </label>
      {state.errors?.body && <p>{state.errors.body[0]}</p>}

      <button disabled={pending}>{pending ? "Posting..." : "Post review"}</button>
      <p aria-live="polite">{state.message}</p>
    </form>
  );
}

"use server";

import { updateTag } from "next/cache";
import { redirect } from "next/navigation";
import { z } from "zod";
import { ApiError, apiFetch } from "@/lib/api";

const Slug = z.string().regex(/^[a-z0-9-]+$/);

const ReviewInput = z.object({
  rating: z.coerce.number().int().min(1, "Pick a rating").max(5),
  title: z.string().trim().min(1, "Give your review a title").max(80),
  body: z.string().trim().min(1, "Write a few words about it").max(2000, "Keep it under 2,000 characters"),
});

export type ReviewState = {
  message?: string;
  errors?: { rating?: string[]; title?: string[]; body?: string[] };
  values?: { rating: string; title: string; body: string };
};

export async function createReview(
  slug: string,
  _previous: ReviewState,
  formData: FormData,
): Promise<ReviewState> {
  const product = Slug.parse(slug);
  const values = {
    rating: String(formData.get("rating") ?? ""),
    title: String(formData.get("title") ?? ""),
    body: String(formData.get("body") ?? ""),
  };
  const parsed = ReviewInput.safeParse(values);
  if (!parsed.success) {
    return { errors: z.flattenError(parsed.error).fieldErrors, values };
  }

  try {
    await apiFetch(`/products/${product}/reviews`, {
      method: "POST",
      body: JSON.stringify(parsed.data),
      session: true,
    });
  } catch (error) {
    if (error instanceof ApiError && error.status === 401) {
      redirect(`/login?next=/products/${product}`);
    }
    if (error instanceof ApiError && error.status === 409) {
      return { message: "You already reviewed this product.", values };
    }
    throw error;
  }

  updateTag(`reviews-${product}`);
  return { message: "Thanks! Your review is up." };
}

"use client";

import { useActionState, useOptimistic } from "react";
import type { Review } from "@/lib/products";
import type { ReviewState } from "./actions";

type Props = {
  reviews: Review[];
  action: (previous: ReviewState, formData: FormData) => Promise<ReviewState>;
};

export function Reviews({ reviews, action }: Props) {
  const [shown, addShown] = useOptimistic(reviews, (list, added: Review) => [...list, added]);

  const [state, formAction, pending] = useActionState(
    async (previous: ReviewState, formData: FormData) => {
      addShown({
        id: "pending",
        rating: Number(formData.get("rating")),
        title: String(formData.get("title")),
        body: String(formData.get("body")),
        author: { name: "You" },
      });
      return action(previous, formData);
    },
    {},
  );

  return (
    <section>
      <ul>
        {shown.map((r) => (
          <li key={r.id} aria-busy={r.id === "pending"}>
            {r.rating} stars, {r.title} by {r.author.name}
          </li>
        ))}
      </ul>
      <form action={formAction}>
        <select name="rating" defaultValue={state.values?.rating ?? ""}>
          <option value="">Rating</option>
          {[5, 4, 3, 2, 1].map((n) => (
            <option key={n} value={n}>{n} stars</option>
          ))}
        </select>
        <input name="title" defaultValue={state.values?.title} />
        <textarea name="body" defaultValue={state.values?.body} />
        <button disabled={pending}>Post review</button>
        <p aria-live="polite">{state.message}</p>
      </form>
    </section>
  );
}
